-- ==================== 12. 平台任务与评估日志 ====================
CREATE TABLE IF NOT EXISTS platform_task_logs (
    log_id VARCHAR(64) PRIMARY KEY,
    time VARCHAR(32) NOT NULL,
    task_type VARCHAR(64) NOT NULL,
    asset_name VARCHAR(128),
    district_name VARCHAR(64),
    disaster_risk_rate DOUBLE,
    resilience_score DOUBLE,
    traffic_guarantee_rate DOUBLE,
    task_status VARCHAR(32) DEFAULT '待处理',
    operator VARCHAR(64),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

DELETE FROM platform_task_logs;


-- ==================== administrative_divisions ====================
-- UPSERT 模式：division_key 已存在则更新，不存在则插入
-- id 保持稳定，不会因重复启动而变化


-- ==================== administrative_division_aliases ====================
-- UPSERT 模式：alias_name 已存在则更新


-- ==================== division_current_status ====================
-- UPSERT: 37 区当前状态指标（source_type = SEED）
ON DUPLICATE KEY UPDATE resilience_score=VALUES(resilience_score), disaster_risk_rate=VALUES(disaster_risk_rate), traffic_guarantee_rate=VALUES(traffic_guarantee_rate), risk_level=VALUES(risk_level), source_type=VALUES(source_type), source_task_id=VALUES(source_task_id), updated_at=VALUES(updated_at);

-- ==================== V1.4B 正式桥隧资产 Seed 数据 ====================
-- 5 座桥梁 + 3 座隧道，sourceType = SEED，幂等 UPSERT

-- transport_assets: 桥梁 (V1.4C: 统一改为 UNBOUND, 无 asset_road_relations)
ON DUPLICATE KEY UPDATE asset_name=VALUES(asset_name), division_id=VALUES(division_id), longitude=VALUES(longitude), latitude=VALUES(latitude), network_binding_status=VALUES(network_binding_status), updated_at=NOW();

-- transport_assets: 隧道 (V1.4C: 统一改为 UNBOUND, 无 asset_road_relations)
ON DUPLICATE KEY UPDATE asset_name=VALUES(asset_name), division_id=VALUES(division_id), longitude=VALUES(longitude), latitude=VALUES(latitude), network_binding_status=VALUES(network_binding_status), updated_at=NOW();

-- bridge_attributes
ON DUPLICATE KEY UPDATE structure_type=VALUES(structure_type), total_length_m=VALUES(total_length_m), max_span_m=VALUES(max_span_m);

-- tunnel_attributes
ON DUPLICATE KEY UPDATE tunnel_type=VALUES(tunnel_type), tunnel_length_m=VALUES(tunnel_length_m);

-- asset_current_status (HOME-2B: OPEN → NORMAL 统一状态枚举)
ON DUPLICATE KEY UPDATE health_score=VALUES(health_score), risk_level=VALUES(risk_level), pass_status=VALUES(pass_status), updated_at=NOW();

